"""Write (never run) a shell script that replaces the history of a public repository with one
commit holding the release tree, then pushes with --force, tags and creates a release."""
import pathlib
import shlex

SCRIPT = """#!/usr/bin/env bash
# Generated by asrun rewrite-history. Read it, then run it by hand. It rewrites public history.
set -euo pipefail
REMOTE={remote}
TREE={tree}
TAG={tag}
MESSAGE={message}
AUTHOR_NAME={author_name}
AUTHOR_EMAIL={author_email}
PY={py}
WORK=$(mktemp -d)

git clone -q "$REMOTE" "$WORK/clone"
cd "$WORK/clone"
git checkout -q --orphan release-single-commit
git rm -rq --cached . || true
find . -mindepth 1 -maxdepth 1 ! -name .git -exec rm -rf {{}} +
rsync -a --exclude .git --exclude __pycache__ "$TREE/" ./
sha256sum -c --quiet SHA256SUMS
"$PY" -I verify_code.py
[ -f verify_payload.py ] && "$PY" -I verify_payload.py
find . -name __pycache__ -type d -prune -exec rm -rf {{}} +
git add -A
GIT_AUTHOR_NAME="$AUTHOR_NAME" GIT_AUTHOR_EMAIL="$AUTHOR_EMAIL" \\
GIT_COMMITTER_NAME="$AUTHOR_NAME" GIT_COMMITTER_EMAIL="$AUTHOR_EMAIL" \\
  git commit -q -m "$MESSAGE"
git branch -D {branch} 2>/dev/null || true
git branch -m {branch}
test "$(git rev-list --count HEAD)" = 1
if git log --format=%B | grep -qi 'co-authored-by'; then echo "co-author line found; stopping"; exit 1; fi
git push --force origin {branch}
git tag -a "$TAG" -m "$TAG"
git push origin "$TAG"
{release}
git archive --format=zip --prefix="release-$TAG/" -o "$WORK/release-$TAG.zip" HEAD

CHECK=$(mktemp -d)
git clone -q "$REMOTE" "$CHECK/c"
(cd "$CHECK/c" && echo "commits: $(git rev-list --count HEAD); author: $(git log --format='%an <%ae>')" \\
   && sha256sum -c --quiet SHA256SUMS && "$PY" -I verify_code.py)
echo "archive: $WORK/release-$TAG.zip"
"""


def write_script(out, remote, tree, tag, message, author_name, author_email, branch="main",
                 py="python3", github_release=True):
    out = pathlib.Path(out)
    if out.exists():
        raise SystemExit(f"{out} exists; not overwritten")
    release = (f'gh release create "$TAG" --title "$TAG" --notes "$MESSAGE"' if github_release
               else "# no hosted release requested")
    q = shlex.quote
    text = SCRIPT.format(remote=q(remote), tree=q(str(pathlib.Path(tree).resolve())), tag=q(tag), message=q(message),
                         author_name=q(author_name), author_email=q(author_email), py=q(py), branch=branch,
                         release=release)
    out.write_text(text, encoding="utf-8")
    out.chmod(0o755)
    return out
